/usr/bin/python3 - <<'PY'
import json, os, pathlib, sys
home = pathlib.Path(os.environ.get("HERMES_HOME", pathlib.Path.home() / ".hermes")).expanduser()
state_path = home / "gateway_state.json"
try:
    state = json.loads(state_path.read_text(encoding="utf-8"))
except FileNotFoundError:
    sys.exit(f"FAIL: gateway state missing: {state_path}")
except (OSError, json.JSONDecodeError) as exc:
    sys.exit(f"FAIL: cannot read gateway state {state_path}: {exc}")
pid = state.get("pid")
if not isinstance(pid, int) or pid <= 0:
    sys.exit(f"FAIL: gateway state has invalid pid: {pid!r}")
try:
    os.kill(pid, 0)
except (ProcessLookupError, PermissionError, OSError) as exc:
    sys.exit(f"FAIL: gateway process pid {pid} is not alive: {exc}")
if state.get("gateway_state") not in ("running", "degraded"):
    sys.exit(f"FAIL: gateway state is {state.get('gateway_state')!r}, expected running")
platforms = state.get("platforms")
if not isinstance(platforms, dict) or not platforms:
    sys.exit("FAIL: gateway state has no platform status entries")
bad = [f"{name}={info.get('state')!r}" for name, info in platforms.items()
       if not isinstance(info, dict) or info.get("state") != "connected"]
if bad:
    sys.exit("FAIL: enabled gateway platforms are not connected: " + ", ".join(bad))
print(f"OK: gateway pid {pid} alive; {len(platforms)} platforms connected")
PY
